            // Tuning: khi tải Trang chủ có nhiều truy vấn chạy song song → nâng giới hạn
            // kết nối đồng thời (mặc định OkHttp chỉ 5 request/host) và đặt timeout hợp lý.
            httpEngine = OkHttp.create {
                config {
